import Foundation
import Testing
@testable import ITDBKit

// A vector generated by Tools/reference-hash58.py on a synthetic database.
// A user's real database does not go into the repository.
private let fixtureFWID = "0123456789ABCDEF"

private let fixtureDatabaseHex =
        "6d686264f400000000020000d5a95a36fab3d83af2a64aec4ac534221c860da5" +
        "1f285f6a9b3b1f5cd315c7caf9891a0a810e3e8e22c7feb07d697bedde0a657b" +
        "94e65e4fac929e7bebc4a53516349ff3525d04617c95c36333231d0446495c05" +
        "43b83855c31e40c5e90cda45f8640a81abcb50cc111b935cb2a9ba4ae6230428" +
        "9fe191bc4800e14bd60779244bb98543a5f90e82d43aa0a135dc5af78b702b33" +
        "4e13d5544d02601d3cc99801218744118907ad600745df0f52cf7f8d352c32d2" +
        "c5eaf90847a7ad89af292cc4da4397c5511851b52a740f446549c3e87d01dc23" +
        "4d02db02614aadbee389e45f47139c13f19169ef52393a3e0b87274df2f37401" +
        "af065f5a53f3582f5bcc8b5ae56bd06d24633f89308580691c5521194b046e85" +
        "631bd865610c532f402c363b3942a6f963f344e95387c6adce577635a40725e1" +
        "d3c5771c4ded9d3cb8e702064493029cee1ff72dd43ce0e6222e1dab7258ad6c" +
        "6bfbe0398dbf9427de503e3af31bcb0b0341deb3f90d38ea3466621c87cf3862" +
        "73ed35cd604110f41be285591e9d4319dbd41b573b0c5abf1d99d2fa0e4017a6" +
        "1ed6452728c16ced63e81f993b4b43c769cb860268f0ffa2b36ed101c492f807" +
        "58d231dbedc26bceaa5f85bd570a4610f81f2c3be66d7b5e06a6bd9e4c4cab08" +
        "a34b6dde2a4ca9d5c07bbbaef935e3b1c1ee045a40378e1fab201765a1210172"

// A vector with the scheme at 0x30, matching an independent port in Python
// (Tools/reference-hash58.py). A script that writes the scheme at 0x72 would give
// a different vector and repeat the bug instead of catching it. On a real database from Apple
// Music, correctness is confirmed by `ipodctl roundtrip` (byte-for-byte agreement).
private let fixtureSignatureHex = "1264be50248f461dd7086d50cde48b2f04a938a5"

private func bytes(fromHex hex: String) -> Data {
    var data = Data(capacity: hex.count / 2)
    var index = hex.startIndex
    while index < hex.endIndex {
        let next = hex.index(index, offsetBy: 2)
        data.append(UInt8(hex[index..<next], radix: 16)!)
        index = next
    }
    return data
}

@Suite("hash58")
struct Hash58Tests {

    @Test("the tables have the right size and are AES S-boxes")
    func tables() {
        #expect(Hash58.table1.count == 256)
        #expect(Hash58.table2.count == 256)
        #expect(Hash58.fixedSalt.count == 18)
        #expect(Array(Hash58.table1.prefix(4)) == [0x63, 0x7C, 0x77, 0x7B])
        // table2 must invert table1
        for value in 0...255 {
            #expect(Hash58.table2[Int(Hash58.table1[value])] == UInt8(value))
        }
    }

    @Test("lcm behaves as in the reference with zeros")
    func leastCommonMultiple() {
        #expect(Hash58.leastCommonMultiple(0, 10) == 1)
        #expect(Hash58.leastCommonMultiple(10, 0) == 1)
        #expect(Hash58.leastCommonMultiple(33, 43) == 1419)
        #expect(Hash58.leastCommonMultiple(136, 103) == 14008)
    }

    @Test("the signature matches the reference vector")
    func signatureMatchesReference() throws {
        let database = bytes(fromHex: fixtureDatabaseHex)
        let fireWireID = try Hash58.fireWireID(fromHex: fixtureFWID)
        let signature = try Hash58.signature(
            fireWireID: fireWireID,
            preparedDatabase: Hash58.prepare(database)
        )
        #expect(signature.hexString == fixtureSignatureHex)
    }

    @Test("sign writes a signature that then verifies")
    func signThenVerify() throws {
        let database = bytes(fromHex: fixtureDatabaseHex)
        let fireWireID = try Hash58.fireWireID(fromHex: fixtureFWID)
        let signed = try Hash58.sign(database, fireWireID: fireWireID)

        #expect(try Hash58.hashingScheme(in: signed) == 1)
        #expect(try Hash58.verify(database: signed, fireWireID: fireWireID).matches)
        #expect(try Hash58.storedSignature(in: signed).hexString == fixtureSignatureHex)
    }

    @Test("changing the data changes the signature, a change in the zeroed fields does not")
    func sensitivity() throws {
        let database = bytes(fromHex: fixtureDatabaseHex)
        let fireWireID = try Hash58.fireWireID(fromHex: fixtureFWID)
        let baseline = try Hash58.signature(
            fireWireID: fireWireID, preparedDatabase: Hash58.prepare(database)
        )

        var payloadChanged = database
        payloadChanged[0x100] ^= 0x01
        #expect(try Hash58.signature(
            fireWireID: fireWireID, preparedDatabase: Hash58.prepare(payloadChanged)
        ) != baseline)

        var zeroedFieldChanged = database
        zeroedFieldChanged[0x18] ^= 0xFF
        zeroedFieldChanged[0x5A] ^= 0xFF
        #expect(try Hash58.signature(
            fireWireID: fireWireID, preparedDatabase: Hash58.prepare(zeroedFieldChanged)
        ) == baseline)

        let otherDevice = try Hash58.fireWireID(fromHex: "0123456789ABCDEE")
        #expect(try Hash58.signature(
            fireWireID: otherDevice, preparedDatabase: Hash58.prepare(database)
        ) != baseline)
    }

    @Test("rejects data that is not an iTunesDB")
    func rejectsGarbage() {
        let notADatabase = Data(repeating: 0x41, count: 512)
        #expect(throws: ITDBError.self) { try Hash58.prepare(notADatabase) }

        let tooSmall = Data("mhbd".utf8) + Data(repeating: 0, count: 16)
        #expect(throws: ITDBError.self) { try Hash58.prepare(tooSmall) }
    }

    @Test("the GUID must be 16 hex characters")
    func fireWireIDParsing() throws {
        #expect(try Hash58.fireWireID(fromHex: "000A27001234ABCD").count == 8)
        #expect(try Hash58.fireWireID(fromHex: "0x000A27001234ABCD") == Hash58.fireWireID(fromHex: "000A27001234ABCD"))
        #expect(throws: ITDBError.self) { try Hash58.fireWireID(fromHex: "ABC") }
        #expect(throws: ITDBError.self) { try Hash58.fireWireID(fromHex: "ZZZZZZZZZZZZZZZZ") }
    }
}
